  document.getElementById('storeSearch')?.addEventListener('input',filterStores);document.getElementById('productSearch')?.addEventListener('input',renderProducts);document.getElementById('orderStore')?.addEventListener('change',()=>{Object.keys(cart).forEach(k=>{delete cart[k];delete cartPrices[k]});renderProducts();renderCart()});
